use kairos_account_contract::{AccountChange, decode_event};

const FIXTURE: &str = "";

fn main() {
    let payload = decode_hex(FIXTURE);
    let event = decode_event(&payload).unwrap();
    assert_eq!(event.account_id.as_str(), "main");
    assert_eq!(event.metadata.sequence.get(), 1);
    assert!(matches!(event.change, AccountChange::StatusChanged(_)));
    print!("{FIXTURE}");
}

fn decode_hex(value: &str) -> Vec<u8> {
    value
        .as_bytes()
        .chunks_exact(2)
        .map(|pair| u8::from_str_radix(std::str::from_utf8(pair).unwrap(), 16).unwrap())
        .collect()
}
